zonaCargada('f','87_-16',{"n:souto-da-retorta--lugo":{"municipio":"Viveiro","resumen":"Monumento natural en Viveiro (Lugo), con 3 ha. Monumento Natural en la parroquia de Chavín (Viveiro), ribera del río Landro. Bosquete de unos 600 eucaliptos centenarios plantados tras 1860 para drenar terreno inundable; incluye 'O Avó de Chavín', el eucalipto más grande de Galicia (altura oficial 61,78 m, perímetro 7,55 m).","web":"https://www.turismo.gal/recurso/-/detalle/16943/souto-da-retorta"},"n:ruta-carinocabo-ortegal--a-coruna":{"municipio":"Cariño","resumen":"Acantilado o tramo de costa en Cariño (A Coruña). Está dentro del Geoparque Mundial UNESCO de Cabo Ortegal.","web":"https://www.paxinasgalegas.es/fiestas/ruta-cari%C3%B1o-cabo-ortegal-26768.html"},"n:cabo-ortegal--a-coruna":{"municipio":"Cariño","resumen":"Acantilado o tramo de costa en Cariño (A Coruña). Punto donde confluyen el mar Cantábrico y el océano Atlántico, en el municipio de Cariño; acantilados entre los más altos de la Península Ibérica, formados por rocas de las más antiguas de Galicia (complejo de Cabo Ortegal, con peridotitas). Mirador natural de gran valor geológico y faunístico (colonias de aves marinas).","web":"https://www.elespanol.com/quincemil/vivir/escapadas/20260426/confirmado-renfe-saca-venta-billetes-euros-ruta-faros-increibles-galicia-trt/1003744216688_0.html"},"n:senda-litoral-de-viveiro-covasarea--lugo":{"municipio":"Viveiro","resumen":"Ruta lineal de 27,6 km en Viveiro (Lugo). Acumula 1.308 m de subida. Se calcula en 8 h 25 min de marcha y su dificultad es muy fácil (1 sobre 5).","web":"https://www.komoot.com/es-es/guide/1542413/rutas-de-senderismo-en-viveiro","rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"n:acantilados_vixia_herbeira":{"municipio":"Cariño / Cedeira","resumen":"Acantilado o tramo de costa en Cariño / Cedeira (A Coruña). Acantilados de la Serra da Capelada, uno de los acantilados costeros más altos de la Europa continental, entre los municipios de Cariño y Cedeira.","rp":["r:mirador-de-herbeira--personal-a-coruna"]},"r:ortigueira--personal-a-coruna":{"municipio":"Ortigueira","resumen":"Ruta de la colección personal de senderismo de Carlos, realizada el 2026-06-29. Datos reales medidos con GPS propio (reloj/app), no estimados.","distancia_km":9.13,"desnivel_positivo_m":240,"tiempo_estimado_horas":2.58,"esf":1,"pp":[["t:banco-de-loiba-el-mejor-banco-del-mundo-ortigueira",5.4]],"fo":["iv",0.1,"",6.0]},"r:o-vicedo--personal-lugo":{"municipio":"O Vicedo","resumen":"Ruta de la colección personal de senderismo de Carlos, realizada el 2026-06-29. Datos reales medidos con GPS propio (reloj/app), no estimados.","distancia_km":4.05,"desnivel_positivo_m":174,"tiempo_estimado_horas":1.52,"esf":0,"fo":["iv",0.1,"",2.9]},"r:mirador-de-herbeira--personal-a-coruna":{"municipio":"Cedeira","resumen":"Ruta de la colección personal de senderismo de Carlos, realizada el 2026-06-28. Datos reales medidos con GPS propio (reloj/app), no estimados. Pasa cerca de otro punto ya catalogado del catálogo nacional, pero es un recorrido distinto.","distancia_km":2.17,"desnivel_positivo_m":95,"tiempo_estimado_horas":0.7,"esf":0,"pp":[["n:acantilados_vixia_herbeira",0]],"fo":["c",0.4,"",1.1]},"r:pr-g-156-costa-do-vicedo--lugo":{"municipio":"O Vicedo","resumen":"Sendero de pequeño recorrido (PR) lineal de 12 km en O Vicedo (Lugo). Acumula unos 360 m de subida y 395 m de bajada, entre 3 y 134 m de altitud. Se calcula en 2 h 40 min de marcha.","web":"https://www.turismo.gal/recurso/-/detalle/170526000694/pr-g-156-costa-do-vicedo","distancia_km":12.0,"desnivel_positivo_m":360,"tiempo_estimado_horas":2.67,"altitud_max_m":134,"esf":2,"fo":["l",4.1,"",13.8]},"r:pr-g-204-ruta-ribeira-do-bispo-miradoiro-de-augas-caidas--a-coruna":{"municipio":"Mañón","resumen":"Sendero de pequeño recorrido (PR) lineal de 11,9 km en Mañón (A Coruña). Acumula unos 124 m de subida y 155 m de bajada, entre 182 y 258 m de altitud. Se calcula en 4 h de marcha.","web":"https://www.turismo.gal/recurso/-/detalle/200525000145/pr-g-204-ruta-ribeira-do-bispo-miradoiro-de-augas-caidas","distancia_km":11.91,"desnivel_positivo_m":124,"tiempo_estimado_horas":4.0,"altitud_max_m":258,"esf":1,"fo":["l",6.3,"",11.8]},"r:pr-g-212-ruta-ponte-do-porto-ponte-ullo--a-coruna":{"municipio":"Mañón","resumen":"Sendero de pequeño recorrido (PR) lineal de 6,3 km en Mañón (A Coruña). Acumula unos 77 m de subida y 110 m de bajada, entre 78 y 134 m de altitud. Se calcula en 1 h 45 min de marcha.","web":"https://www.turismo.gal/recurso/-/detalle/200527000188/pr-g-212-ruta-ponte-do-porto-ponte-ullo","distancia_km":6.32,"desnivel_positivo_m":77,"tiempo_estimado_horas":1.75,"altitud_max_m":134,"esf":0,"pp":[["t:ponte-do-porto-rio-barba-vicedo",0],["t:capilla-de-las-angustias-de-rio-barba-vicedo",0]],"fo":["l",3.5,"",6.3]},"r:pr-g-8-morgallon-rio-sor-morgallon--lugo":{"municipio":"O Vicedo","resumen":"Sendero de pequeño recorrido (PR) circular de 8,3 km en O Vicedo (Lugo). Acumula unos 223 m de subida, entre 40 y 129 m de altitud. Se calcula en 3 h de marcha.","web":"https://www.turismo.gal/recurso/-/detalle/33804/pr-g-8-morgallon-rio-sor-morgallon","distancia_km":8.26,"desnivel_positivo_m":223,"tiempo_estimado_horas":3.0,"altitud_max_m":129,"esf":1,"fo":["c",0.0,"",8.2]},"r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia":{"municipio":"Ortigueira","resumen":"Ruta lineal de 156 km en Ortigueira (A Coruña, Lugo). Se divide en 16 etapas. Acumula unos 2.599 m de subida y 2.519 m de bajada, entre 0 y 161 m de altitud. Se calcula en 39 h 30 min de marcha en total. Atraviesa en parte la Reserva de la Biosfera de Río Eo, Oscos y Terra de Burón y el Geoparque Mundial UNESCO de Cabo Ortegal.","web":"https://www.mapa.gob.es/caminosnaturales","distancia_km":155.58,"desnivel_positivo_m":2599,"tiempo_estimado_horas":39.5,"altitud_max_m":161,"esf":1,"pp":[["t:pazo-de-guimaran-ribadeo",0.3],["t:fuerte-de-san-damian-ribadeo",1.1],["t:barrio-de-rinlo-ribadeo",10.5],["n:praia_das_illas_ribadeo",14.3],["n:monumento-natural-de-la-praia-das-catedrais-praia-de-augas-santas--lugo",16.5],["t:capela-de-san-bartolo-barreiros",23.8],["t:cabozo-dos-moreda-barreiros",26.1],["h:fazouro",44.6],["t:antiga-fabrica-de-gres-cucurny-burela",54.5],["t:barco-museo-boniteiro-reina-del-carmen-burela",54.5],["t:castro-de-burela-chao-do-castro-burela",55.6],["t:pazo-de-pedrosa-cervo",63.5],["t:faro-de-san-cibrao-punta-atalaia-cervo",65.5],["t:capilla-de-san-cibrao-cervo",65.7],["t:ruinas-de-la-fabrica-de-salazon-de-punta-atalaia-cervo",65.8],["t:museo-provincial-do-mar-cervo",66.2],["t:fabricas-de-salazon-y-aserradero-de-don-julian-cervo",66.4],["t:ponte-medieval-do-bao-cervo",67.3],["n:senda-litoral-de-viveiro-covasarea--lugo",94.7],["t:puerta-de-carlos-v-vivero",94.7],["t:iglesia-de-santiago-antiguo-convento-de-san-francisco-vivero",94.7],["t:rua-do-muro-vivero",94.9],["t:casa-dos-leons-vivero",94.9],["t:casas-con-galerias-de-la-travesia-da-marina-vivero",94.9],["t:iglesia-de-santalla-de-ladrido-el-cura-reloxeiro-ortigueira",139.0],["t:porto-de-espasante-ortigueira",142.1],["t:casa-da-vela-espasante-ortigueira",142.6],["t:banco-de-loiba-el-mejor-banco-del-mundo-ortigueira",151.6],["t:muino-de-vento-de-o-picon-ortigueira",152.6],["t:o-barqueiro-manon",158.7],["t:puente-metalico-de-o-barqueiro-manon",159.7]],"fo":["l",50.4,"",175.4]},"n:geoparque-mundial-unesco-de-cabo-ortegal--a-coruna":{"municipio":"Cerdido","resumen":"Geoparque mundial de la UNESCO en Cerdido (A Coruña), con 79.975 ha.","web":"https://xeoparquecaboortegal.gal/"},"t:circulo-litico-de-somede-puentes-de-garcia-rodriguez":{"municipio":"Puentes de García Rodríguez","resumen":"Círculo de piedras de unos 9,4 m de diámetro en el alto de O Bidueiral, entre las parroquias de Somede y O Freixo. Según el estudioso Ramón Boga es el único círculo lítico conservado in situ en Galicia. Pasa casi desapercibido, pero tiene una entrada orientada a levante marcada por cinco pequeñas losas de pizarra hincadas.","ver_alli":["Corredor de entrada con cinco losas verticales","Vistas al valle del Eume"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/23206/circulo-litico-de-somede"]},"t:ermida-da-nosa-senora-da-pena-de-francia-solloso-puentes-de-garcia-rodriguez":{"municipio":"Puentes de García Rodríguez","resumen":"Santuario fundado en el siglo XVII por los condes de Montenegro a imitación del de la Peña de Francia de Salamanca, reformado en 1929-1931. De la obra original conserva el pórtico de entrada con dos columnas gruesas y la pequeña espadaña. Los vecinos cuentan una leyenda de dos hermanas enemistadas que explicaría su origen.","ver_alli":["Pórtico a tres aguas sobre columnas","Antigua imagen de la Peña de Francia en retablo neogótico"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/23217/ermida-da-nosa-senora-da-pena-de-francia"]},"t:iglesia-de-san-xoan-do-freixo-puentes-de-garcia-rodriguez":{"municipio":"Puentes de García Rodríguez","resumen":"La iglesia parroquial más grande del municipio, fundada en el siglo XVII por los condes de Montenegro. Nació con planta de cruz latina y luego se elevó y se amplió a tres naves. Su torre barroca de tres cuerpos con cúpula se une al pórtico de entrada.","ver_alli":["Torre barroca del siglo XVII","Retablos laterales barrocos","Osario con plegaria de 1868 en el muro"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/23242/igrexa-parroquial-de-san-xoan-do-freixo"]},"t:centro-etnografico-o-seixidal-as-somozas":{"municipio":"As Somozas","resumen":"Centro de interpretación del patrimonio etnográfico de la comarca, en la parroquia de Enchousas. Muestra la forma de vida rural tradicional, ya casi desaparecida. Recoge tanto objetos como tradiciones y memoria oral.","ver_alli":["Útiles de la vida rural tradicional"],"visita":"desconocido","fuentes":["https://www.turismo.gal/recurso/-/detalle/260925000152/centro-etnografico-o-seixidal"]},"t:machuco-de-as-somozas-as-somozas":{"municipio":"As Somozas","resumen":"Restos de un mazo hidráulico de herrero ('machuco') junto al río Grande de Xubia. Conserva los muros de mampostería y parte de la carpintería y piezas interiores. Está en un paraje fluvial muy bonito.","ver_alli":["Canal de agua que movía el mazo","Restos de la maquinaria de madera"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/21435/machuco-de-as-somozas"]},"t:forxa-de-castelo-as-somozas":{"municipio":"As Somozas","resumen":"Pequeña fragua tradicional que conserva yunque y fuelle junto a herramientas más modernas.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/21434/forxa-de-castelo"]},"t:iglesia-de-san-pedro-das-enchousas-as-somozas":{"municipio":"As Somozas","resumen":"Iglesia rural gótica de una nave con una pequeña capilla de dos estancias cubiertas con bóveda de crucería. Una inscripción del muro sur dice que la capilla fue de la marquesa de Cavalcanti. El altar tiene un retablo neoclásico pintado imitando mármol.","ver_alli":["Bóveda de crucería de una clave","Inscripción de la marquesa de Cavalcanti"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/22688/igrexa-de-san-pedro-de-enchousas"]},"t:iglesia-de-santiago-sere-das-somozas-as-somozas":{"municipio":"As Somozas","resumen":"Iglesia barroca del siglo XVIII de tres naves, con bóveda rebajada de madera en la central y coro alto de madera. El gran campanario termina en una cúpula octogonal con cruz de hierro. En la parte trasera del presbiterio aparecen jabalíes y escudos de los Andrade.","ver_alli":["Jabalíes de los Andrade en el presbiterio","Techumbres de madera","Campanario con cúpula octogonal"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/22693/igrexa-de-santiago-sere"]},"t:iglesia-de-santa-maria-de-recemel-as-somozas":{"municipio":"As Somozas","resumen":"Iglesia barroca de tres naves con cubiertas de madera y arcos sobre pilares bajos. El pequeño presbiterio reproduce por dentro, con estructura de madera, las cuatro aguas del tejado. Su campanario tiene cúpula octogonal con pináculo.","ver_alli":["Estructura de madera vista en el presbiterio","Coro alto de madera"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/22691/igrexa-de-santa-maria-de-recemel"]},"t:escuela-aurora-de-as-somozas-habana-as-somozas":{"municipio":"As Somozas","resumen":"Escuela de los años 30 pagada por emigrantes en Cuba, que funcionó hasta la Guerra Civil.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/22695/aurora-de-as-somozas-habana"]},"t:capela-de-san-xiao-dos-osos-moeche":{"municipio":"Moeche","resumen":"Pequeña capilla de vieja tradición en el antiguo camino de peregrinos a San Andrés de Teixido. Una obra de 1973 le quitó casi toda la decoración exterior, salvo el escudo del monasterio de Oseira, gran propietario en la parroquia hasta el siglo XIX. Dentro, dos sarcófagos medievales flanquean la entrada del siglo XVIII a la segunda estancia.","ver_alli":["Dos sarcófagos medievales","Escudo del monasterio de Oseira en la trasera"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/191209000103/capela-de-san-xiao-dos-osos"]},"t:iglesia-de-san-xurxo-de-moeche-moeche":{"municipio":"Moeche","resumen":"Iglesia rural barroca cuyas partes más antiguas podrían ser del siglo XI, junto al castillo de Moeche. Su capilla mayor tiene una bóveda de nervios en estrella. Una capilla lateral, pagada por la Casa de Rañal, lleva su escudo y los monogramas de Jesús y María.","ver_alli":["Bóveda estrellada de la capilla mayor","Heráldica de la Casa de Rañal","Torre de tres cuerpos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/24883/igrexa-de-san-xurxo"]},"t:iglesia-de-santa-cruz-de-moeche-moeche":{"municipio":"Moeche","resumen":"Iglesia de barroco rural, la única del concello con planta de cruz latina y crucero abovedado.","visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/24884/igrexa-de-santa-cruz-de-moeche"]},"t:iglesia-de-san-martino-de-cerdido-cerdido":{"municipio":"Cerdido","resumen":"Pequeña iglesia de planta de cruz latina que suma estilos de varias épocas. Conserva muestras de gótico isabelino del siglo XVI: dos puertas con arcos carpaneles en la fachada y la bóveda del presbiterio. Dentro guarda tres retablos barrocos, y por fuera escudos, torre y una pequeña espadaña.","ver_alli":["Dos puertas con arco carpanel","Bóveda gótica del presbiterio","Tres retablos barrocos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/24653/igrexa-parroquial-de-san-martino-de-cerdido"]},"t:pazo-de-vila-da-igrexa-cerdido":{"municipio":"Cerdido","resumen":"Pequeño pazo de aire hermético y señorial que perteneció a la casa de los Andrade.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/19747/pazo-de-vila-da-igrexa"]},"t:iglesia-de-san-anton-da-barqueira-cerdido":{"municipio":"Cerdido","resumen":"Iglesia neogótica de 1920 en cruz, con un cruceiro de piedra de Moeche de 1900 con inscripción.","visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/180205000048/igrexa-san-anton-a-barqueira"]},"t:casa-indiana-de-a-barqueira-cerdido":{"municipio":"Cerdido","resumen":"Casa indiana del XIX con molduras de arabescos vegetales de influencia modernista y jardín frondoso.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/24676/casa-indiana-en-a-barqueira"]},"t:santuario-de-san-andres-de-teixido-cedeira":{"municipio":"Cedeira","resumen":"Santuario gótico-barroco de los siglos XVI y XVIII colgado sobre los acantilados de A Capelada, uno de los grandes lugares de peregrinación de Galicia ('vai de morto quen non foi de vivo'). De la iglesia anterior quedan la puerta norte y pinturas murales. Guarda un relicario barroco italiano con un fragmento de hueso de San Andrés.","ver_alli":["Relicario con hueso de San Andrés","Pinturas murales","Torre del siglo XVIII de tres cuerpos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5011/igrexa-de-santo-andre-de-teixido","https://es.wikipedia.org/wiki/Santuario_de_San_Andr%C3%A9s_(Teixido)"]},"t:fonte-de-san-andres-de-teixido-cedeira":{"municipio":"Cedeira","resumen":"Fuente de tres caños de 1781 junto al santuario, encalada como el resto del pueblo. Según la tradición se echa una miga de pan al agua y se pide un deseo. Si flota, el deseo se cumple; si se hunde, mala suerte.","ver_alli":["Tres caños de piedra","Ritual de la miga de pan"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/17625/fonte-de-san-andres-de-teixido"]},"t:iglesia-de-santa-marta-y-antiguo-convento-de-los-dominicos-ortigueira":{"municipio":"Ortigueira","resumen":"Conjunto conventual de unos 5.000 m² en el centro de Ortigueira. El convento dominico es de la primera mitad del siglo XIV, se expropió en 1835 y hoy alberga dependencias municipales en torno a su claustro. La iglesia neoclásica se rehízo de nueva planta en 1776-1799 tras un incendio y conserva los retablos del altar mayor, atribuido a Juan Domínguez de Estivada, y del Rosario.","ver_alli":["Claustro del convento","Tres escudos de piedra con emblemas de la villa","Retablo mayor policromado"],"visita":"iglesia en horario de culto; dependencias municipales lunes a viernes 8-15","fuentes":["https://www.turismo.gal/recurso/-/detalle/4994/igrexa-de-santa-marta-de-ortigueira","https://www.turismo.gal/recurso/-/detalle/6931/antigo-conxunto-conventual","https://www.turismo.gal/recurso/-/detalle/19944/os-dominicos"]},"t:teatro-da-beneficencia-ortigueira":{"municipio":"Ortigueira","resumen":"Teatro instalado en las antiguas despensa, bodega y granero del convento dominico, con planos de 1867 y una ampliación en 1886 porque se quedó pequeño. Tiene platea en ligera pendiente con acceso directo desde el claustro y palcos. Una reforma reciente modernizó escenario y vestíbulos conservando el edificio histórico.","ver_alli":["Platea con palcos","Acceso desde el claustro conventual"],"visita":"en funciones","fuentes":["https://devcarq.gnoss.com/en/resource/theatre-of-the-beneficence-in-santa-marta-de/6e2a086b-2070-47ba-8a92-e170ec3eafc6","https://nominatim.openstreetmap.org/search?q=Teatro+da+Beneficencia&format=json"]},"t:muino-de-vento-do-campo-da-torre-ortigueira":{"municipio":"Ortigueira","resumen":"Molino de viento de 1888 en lo alto de la colina que domina la villa, donde hubo una fortaleza medieval y un castro (se conserva su foso). Tras décadas en ruinas se reconstruyó fielmente en 2005 y puede volver a moler. Tiene cuerpo cilíndrico, tejado cónico giratorio y cuatro pares de aspas.","ver_alli":["Aspas y cubierta giratoria","Piedras para trigo y maíz","Foso del antiguo castro"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/181221000192/muino-de-vento-do-campo-da-torre"]},"t:muino-de-vento-de-o-picon-ortigueira":{"municipio":"Ortigueira","resumen":"Molino de viento de torre cilíndrica de la década de 1880 en Loiba, hoy sin cubierta y de propiedad privada.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/181221000191/muino-de-o-picon"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:muino-de-marea-de-pol-ortigueira":{"municipio":"Ortigueira","resumen":"Molino de mareas construido entre 1905 y 1910 por un emigrante retornado de Cuba, al fondo de la ría de Ortigueira. Una presa recoge el agua con la marea alta y la suelta al bajar para mover las muelas. Con la marea alta, la parte baja del edificio queda medio sumergida bajo sus siete arcos.","ver_alli":["Dique con compuerta de madera","Siete arcos del cárcavo"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/20045/muino-de-marea-de-pol"]},"t:castro-de-punta-dos-prados-ortigueira":{"municipio":"Ortigueira","resumen":"Pequeño poblado fortificado costero de entre los siglos IV y I a. C., en una península junto a la playa de A Concha de Espasante. Dos fosos en U y dos murallas de piedra y tierra aislaban la zona habitada. Lo más destacado es un monumento con horno, una sauna o baño castreño.","ver_alli":["Sauna o baño castreño","Fosos y murallas","Acceso desde el puerto de Espasante"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/231129000473/castro-de-punta-dos-prados"]},"t:forno-dos-mouros-ortigueira":{"municipio":"Ortigueira","resumen":"Necrópolis neolítica de nueve túmulos en el alto de la sierra da Coriscada, de los que dos se excavaron y se prepararon para la visita. El túmulo 5 guardaba una cámara megalítica de hacia el 4400 a. C. Esa cámara se llevó al Museo Ortegalia para conservarla.","ver_alli":["Dos túmulos excavados y visitables"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/231129000482/forno-dos-mouros"]},"t:casa-da-vela-espasante-ortigueira":{"municipio":"Ortigueira","resumen":"Edificio de piedra neoclásico de mediados del siglo XVIII en un punto estratégico sobre la ría de Ortigueira. En 1703 el párroco de Espasante pidió defensas contra los saqueos de ingleses y holandeses, y aquí se puso una garita de vigilancia con un pequeño destacamento. Por dentro aún conserva una antigua lareira.","ver_alli":["Antigua lareira","Vista de la ría, Cariño y Espasante"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/23839/casa-da-vela"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:porto-de-espasante-ortigueira":{"municipio":"Ortigueira","resumen":"Pueblo marinero de calles estrechas que bajan hasta el arenal de A Concha, poblado sin interrupción desde época castreña. Conserva casas con corredor de balaustres y naves de las antiguas salazones y conserveras del XIX y principios del XX. Mantiene la tradición del cerdo de San Antón, alimentado por los vecinos.","ver_alli":["Casas con corredor abalaustrado","Antiguas naves conserveras"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/278483507/barrio-de-espasante"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:antiguo-grupo-escolar-de-ortigueira-ortigueira":{"municipio":"Ortigueira","resumen":"Escuela diseñada por el arquitecto modernista Julio Galán en la primera década del siglo XX. La promovió el diputado Juan Fernández Latorre y la pagaron a medias el Estado y el Ayuntamiento. Su cuerpo central lleva los escudos de Ortigueira, A Coruña y Galicia; hoy es biblioteca y archivo.","ver_alli":["Tres escudos en el cuerpo central"],"visita":"exterior libre; biblioteca en su horario","fuentes":["https://www.turismo.gal/recurso/-/detalle/23841/edificio-do-antigo-grupo-escolar"]},"t:asilo-dolores-diaz-davila-ortigueira":{"municipio":"Ortigueira","resumen":"Asilo indiano de 1929 pagado por el emigrante Eusebio Dávila, con doble escalinata y jardines sobre el paseo de Miñano.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/23842/edificio-do-asilo-dolores-diaz-davila"]},"t:iglesia-de-san-cristovo-de-couzadoiro-ortigueira":{"municipio":"Ortigueira","resumen":"Iglesia rural barroca de los siglos XVII-XVIII de cruz latina. En un brazo del crucero tiene dos retablos de madera policromada. Guarda una curiosa Virgen Negra de Loreto y tiene un atrio cubierto para resguardar a los fieles de la lluvia.","ver_alli":["Virgen Negra de Loreto","Dos retablos policromados","Atrio cubierto"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/4987/igrexa-de-san-cristobal-de-couzadoiro"]},"t:iglesia-de-santalla-de-ladrido-el-cura-reloxeiro-ortigueira":{"municipio":"Ortigueira","resumen":"Iglesia citada ya en el siglo XII, rediseñada en 1799-1800 por su párroco, Francisco Javier Cayetano Méndez y Neira, el 'Cura Reloxeiro'. Montó un taller de relojería en la rectoral del que salieron piezas para el monasterio de Sobrado y para la Casa Real de Carlos IV. El templo es de cruz latina con accesos laterales cubiertos.","ver_alli":["Rectoral donde estuvo el taller de relojes","Accesos laterales cubiertos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/190124000386/igrexa-de-santa-eulalia-de-ladrido","https://www.wikidata.org/wiki/Q135472005"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:pazo-de-brandaliz-ortigueira":{"municipio":"Ortigueira","resumen":"Pazo barroco de origen en el siglo XV, rodeado por una larga muralla con portón. Su edificio en L tiene almenas decorativas y escalinata de piedra, y en la fachada un escudo con las armas de las familias ligadas a la casa. Lo completan una capilla de San Miguel y jardines geométricos.","ver_alli":["Escudo de armas","Almenas sin uso militar","Capilla de San Miguel"],"visita":"privado; solo exterior","fuentes":["https://www.turismo.gal/recurso/-/detalle/6932/pazo-de-brandaliz"]},"t:banco-de-loiba-el-mejor-banco-del-mundo-ortigueira":{"municipio":"Ortigueira","resumen":"Banco de madera colocado en 2009 por un vecino sobre los acantilados de Loiba. En 2010, durante el Festival de Ortigueira, alguien escribió en el respaldo 'The best bench of the world', y la frase se repite cada vez que se renueva. La vista abarca la costa desde Estaca de Bares hasta Cabo Ortegal.","ver_alli":["Inscripción 'The best bench of the world'","Vista de Estaca de Bares a Cabo Ortegal"],"visita":"acceso libre","fuentes":["https://www.atlasobscura.com/places/el-mejor-banco-del-mundo-the-best-bench-in-the-world","https://nominatim.openstreetmap.org/search?q=Banco+de+Loiba&format=json"],"rp":["r:ortigueira--personal-a-coruna","r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:iglesia-de-santa-maria-de-manon-y-sus-pinturas-murales-manon":{"municipio":"Mañón","resumen":"Iglesia rural que guarda en el muro norte de la nave un ciclo de pinturas murales pintado en dos fases, entre el último cuarto del siglo XV y la primera mitad del XVI. Representa al menos quince escenas de la Pasión, desde la Entrada en Jerusalén hasta la Crucifixión, rematadas con el Juicio Final. Una intervención de urgencia en 1998 frenó su deterioro, pero aún necesita una restauración completa.","ver_alli":["Ciclo de la Pasión en el muro norte","Santa Cena y Beso de Judas","Juicio Final"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/231018000335/igrexa-santa-maria-de-manon","https://dialnet.unirioja.es/descarga/articulo/7336378.pdf"]},"t:ponte-do-porto-manon-manon":{"municipio":"Mañón","resumen":"Puente de tres arcos de medio punto sobre el Sor, probablemente medieval sobre cimientos romanos; sus sillares se parecen a los de la muralla de Lugo. En el centro, a unos 10 m sobre el agua, tiene un miliario que marcaba el límite entre las antiguas provincias de Betanzos y Mondoñedo.","ver_alli":["Miliario-mojón en el centro del puente","Tres arcos de medio punto"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/6938/ponte-romana-do-porto","https://www.turismo.gal/recurso/-/detalle/19550/ponte-de-malvide"]},"t:pazo-y-torre-de-lama-manon":{"municipio":"Mañón","resumen":"Pazo del siglo XV levantado sobre una antigua fortaleza en el estuario del Sor, de la que quedan sillares en la base y un arco interior que daba al puente levadizo. Su fachada austera lleva el escudo de los Lama y los Maciñeira. Lo rodea una de las mayores plantaciones de camelias del mundo.","ver_alli":["Escudo de Lama y Maciñeira","Plantación de camelias"],"visita":"privado; solo exterior","fuentes":["https://www.turismo.gal/recurso/-/detalle/19740/pazo-de-lama","https://www.turismo.gal/recurso/-/detalle/6937/torre-de-lama"]},"t:muinos-de-bares-manon":{"municipio":"Mañón","resumen":"Serie de pequeños molinos hidráulicos de rodezno que bajan encadenados por la fuerte pendiente del acantilado hasta el mar, junto al faro de Estaca de Bares. Cada uno tiene dos plantas: abajo el cárcavo con la rueda horizontal y arriba la muela. Estaban pendientes de un plan de restauración.","ver_alli":["Molinos escalonados en el acantilado","Rodeznos de madera y metal"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/25392/molinos-de-bares"]},"t:faro-de-estaca-de-bares-manon":{"municipio":"Mañón","resumen":"Faro de 1859 sobre los acantilados más septentrionales de la Península, donde se encuentran el Atlántico y el Cantábrico. Su escalera interior se fundió en la Real Fábrica de Sargadelos. Cerca hay un observatorio de aves y una antigua base militar norteamericana abandonada.","ver_alli":["Escalera de hierro de Sargadelos","Observatorio ornitológico","Antigua base estadounidense"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/19754/cabo-de-estaca-de-bares","https://es.wikipedia.org/wiki/Faro_de_Estaca_de_Bares"]},"t:puente-metalico-de-o-barqueiro-manon":{"municipio":"Mañón","resumen":"Puente de vigas de hierro forjado de 1901 sobre la ría de O Barqueiro, que une las provincias de A Coruña y Lugo. Dejó sin trabajo al barquero que pasaba gente y mercancías y que dio nombre al pueblo. Es más interesante por su ingeniería que por su arquitectura.","ver_alli":["Tres tramos de vigas de hierro","Vista de la ría del Sor"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/6935/ponte-metalico-del-barquero","https://es.wikipedia.org/wiki/Puente_met%C3%A1lico_del_Barquero"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:o-barqueiro-manon":{"municipio":"Mañón","resumen":"Pueblo marinero de casas apiñadas sobre la ría, que debe su nombre al barquero que cruzaba la ría hasta 1901.","visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/278483541/barrio-de-o-barqueiro"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:conjunto-parroquial-de-san-mamede-das-granas-do-sor-manon":{"municipio":"Mañón","resumen":"Iglesia parroquial que, junto con la casa rectoral, el patio, los hornos y los alpendres, se restauró de forma tradicional. El resultado es un conjunto rural completo en el valle alto del Sor. La ficha oficial lo califica de visita obligada.","ver_alli":["Casa rectoral restaurada","Hornos y alpendres"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/231018000321/igrexa-de-san-mamede-das-granas-do-sor"]},"t:ermida-de-san-xiao-do-trebo-carino":{"municipio":"Cariño","resumen":"Ermita levantada sobre un antiguo asentamiento romano, con vistas a la ría de Ortigueira. Junto a ella hay un hórreo y la fuente de los Dos Cabritos. Es meta de una romería tradicional a la que se sube por el Camiño dos Romeiros.","ver_alli":["Fuente de los Dos Cabritos","Hórreo","Vistas a la ría"],"visita":"exterior libre","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-cariño-20tay.html","https://www.wikidata.org/wiki/Q135476882"]},"t:iglesia-de-san-bartolomeu-de-carino-carino":{"municipio":"Cariño","resumen":"Iglesia neogótica terminada en 1923, con una campana que procede del vapor Miramar.","visita":"horario de culto","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-cariño-20tay.html","https://www.wikidata.org/wiki/Q135476862"]},"t:barrio-marinero-de-carino-carino":{"municipio":"Cariño","resumen":"Casco viejo de casas marineras de colores, algunas colgadas sobre los acantilados entre la playa de A Concha y Punta Gabeira. Es el núcleo original de un pueblo que vive del puerto pesquero más importante de la zona. En lo alto está el mirador do Pósito.","ver_alli":["Casas colgadas sobre el acantilado","Miradoiro do Pósito, frente a Estaca de Bares"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/278510798/zona-vella-de-carino","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-cariño-20tay.html"]},"t:miradoiro-do-posito-carino":{"municipio":"Cariño","resumen":"Atalaya en lo alto de la villa frente a los acantilados y la punta de Estaca de Bares.","visita":"acceso libre","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-cariño-20tay.html","https://nominatim.openstreetmap.org/search?q=Miradoiro+do+P%C3%B3sito&format=json"]},"t:castro-da-moura-carino":{"municipio":"Cariño","resumen":"Asentamiento costero de origen prehistórico, del siglo IV a. C. según la fuente. Conserva muralla y foso. Incluye una pequeña isla unida a tierra.","ver_alli":["Muralla y foso"],"visita":"acceso libre","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-cariño-20tay.html","https://nominatim.openstreetmap.org/search?q=Castro+da+Moura&format=json"]},"t:pazo-da-cerca-carino":{"municipio":"Cariño","resumen":"Pazo privado de líneas sencillas con galería al sur, pináculos en la cornisa y dos escudos sobre la entrada.","visita":"privado; solo exterior","fuentes":["https://www.turismo.gal/recurso/-/detalle/9141/pazo-da-cerca"]},"t:puerta-de-carlos-v-vivero":{"municipio":"Vivero","resumen":"Es la puerta principal de la antigua muralla de Viveiro, levantada en 1548 por Pedro Pedroso en homenaje al emperador Carlos V. Sustituyó a otra anterior y en 1942 fue declarada Monumento Nacional. Es la más vistosa de las tres puertas que quedan de la cerca medieval.","ver_alli":["Busto del emperador sobre un frontón y gran escudo imperial de marco plateresco","Seis troneras y tres torrecillas rematando la fachada","Camarín plateresco en la cara interior"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/6940/porta-de-carlos-v?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:porta-da-vila-o-del-cristo-do-amparo-vivero":{"municipio":"Vivero","resumen":"Otra de las tres puertas conservadas de la muralla de Viveiro, la entrada principal por la antigua calzada. Es un arco sencillo de medio punto con bóveda de cañón. Una lápida la fecha en 1217, en tiempos del rey Alfonso IX.","ver_alli":["Lápida interior con la inscripción \"Era M CC L V\" (año 1217)","Vitrina con el Cristo del Amparo (s. XVIII) acompañado de la Virgen y San Juan (s. XVI)","Desemboca en la calle Rosalía de Castro, de casas antiguas y nobles"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/6942/porta-da-vila-ou-do-cristo-do-amparo?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"]},"t:porta-do-valado-vivero":{"municipio":"Vivero","resumen":"Tercera puerta conservada de la muralla de Viveiro, la que daba a la antigua calzada romana. Se considera del siglo XIII aunque de origen más antiguo. Está declarada Bien de Interés Cultural.","ver_alli":["Restos de la muralla primitiva a ambos lados, en la calle Nicolás Cora","Acceso desde la Calexa das Monxas"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/22651/porta-do-valado?langId=es_ES"]},"t:rua-do-muro-vivero":{"municipio":"Vivero","resumen":"Pasadizo de poco más de metro y medio de ancho que formaba parte del adarve de la muralla medieval. Se considera una de las calles más estrechas de España. Es una curiosidad que se recorre en un minuto en pleno casco histórico.","ver_alli":["Anchura de apenas metro y medio entre muros","Trazado del antiguo camino de ronda de la muralla"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/30859/rua-do-muro?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:casa-dos-leons-vivero":{"municipio":"Vivero","resumen":"Fachada de un antiguo pazo renacentista tardío del siglo XVII, lo único que se conserva del edificio. Debe su nombre a los dos leones que sujetan el escudo de armas de la puerta. Destaca por la elegancia y armonía de su composición.","ver_alli":["Escudo sostenido por dos leones sobre la puerta principal","Fachada en piedra en la calle Pastor Díaz, 12"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/30860/casa-dos-leons?langId=es_ES"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:iglesia-de-santa-maria-do-campo-vivero":{"municipio":"Vivero","resumen":"Iglesia románica de la segunda mitad del siglo XII, considerada una de las iglesias urbanas más puras y completas de Galicia. Tiene planta basilical de tres naves y ábside semicircular. La iglesia y su entorno están declarados Monumento y Conjunto Histórico-Artístico.","ver_alli":["Ábside semicircular con arquillos sobre columnillas","Cruz procesional de plata flordelisada del siglo XVI","Grupo escultórico de Las Angustias"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5005/igrexa-parroquial-de-santa-maria-do-campo?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"]},"t:iglesia-de-santiago-antiguo-convento-de-san-francisco-vivero":{"municipio":"Vivero","resumen":"Iglesia del antiguo convento franciscano, de los siglos XIII-XIV, que mezcla portada románica y cabecera gótica. Su ábside poligonal con cinco ventanas ojivales se considera de los más esbeltos de las iglesias conventuales gallegas. Guarda los sepulcros de la beata Constanza de Castro y del escritor Nicomedes Pastor Díaz.","ver_alli":["Ábside pentagonal con bóveda de abanico y ventanales ojivales","Sepulcro de Nicomedes Pastor Díaz","Locales con imágenes procesionales de la Semana Santa"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5002/igrexa-parroquial-de-santiago?langId=es_ES","https://www.turismo.gal/recurso/-/detalle/5601/san-francisco?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:convento-de-las-concepcionistas-vivero":{"municipio":"Vivero","resumen":"Convento de clausura del siglo XVII, de estilo barroco, situado frente a Santa María do Campo. En su iglesia está el sepulcro de su fundadora, María de Alas Pumariño. Junto a él se construyó en 1925 una gruta de Lourdes muy venerada en la villa.","ver_alli":["Sepulcro de la fundadora María de Alas Pumariño","Gruta de Lourdes de 1925, con velas y ofrendas de los vecinos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5513/convento-das-concepcionistas?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"]},"t:monasterio-de-valdeflores-vivero":{"municipio":"Vivero","resumen":"Monasterio de monjas dominicas a las afueras de Viveiro, de origen en el siglo XIV, con iglesia de trazas románicas y góticas. Está declarado Bien de Interés Cultural. Guarda un Lignum Crucis y la imagen de la Virgen de Valdeflores, que según la leyenda halló un campesino bajo tierra.","ver_alli":["Imagen de la Virgen de Valdeflores","Relicario del Lignum Crucis","Retablo mayor de José Otero Gorrita"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5007/mosteiro-de-valdeflores?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"]},"t:puente-de-la-misericordia-ponte-maior-vivero":{"municipio":"Vivero","resumen":"Puente sobre el Landro de origen posiblemente romano, que según la tradición dio nombre a la villa (Vivario). La obra actual se terminó en 1544 y tenía doce arcos, de los que hoy se conservan nueve. Fue ensanchado varias veces entre 1878 y 1982.","ver_alli":["Nueve arcos, los extremos de medio punto y el resto apuntados","Cruz de piedra en el centro del puente con inscripción"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/6939/ponte-da-misericordia?langId=es_ES","https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html"]},"t:casas-con-galerias-de-la-travesia-da-marina-vivero":{"municipio":"Vivero","resumen":"Hilera de casas frente a la ría con las típicas galerías blancas acristaladas de la costa lucense. Son edificios de tres o cuatro plantas de granito y pizarra con galerías que ocupan toda la fachada. Forman una de las estampas más fotografiadas de Viveiro.","ver_alli":["Fachada continua de galerías blancas frente a la ría","Muros de sillería con cubiertas de pizarra"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/22643/casas-con-galerias-tipicas-da-trav.da-marina?langId=es_ES","https://www.turismo.gal/recurso/-/detalle/7280/galerias?langId=es_ES"],"rp":["r:camino-natural-de-la-ruta-del-cantabrico-tramo-de-galicia--galicia"]},"t:coleccion-etnografica-y-de-ceramica-regal-xunqueira-vivero":{"municipio":"Vivero","resumen":"Museo privado instalado en una antigua fábrica de curtidos que llegó a ser la mayor de Galicia y funcionó hasta 1962. Ocupa más de 2.000 m2 de edificios con un jardín central. Reúne colecciones etnográficas y de cerámica.","ver_alli":["Edificios de la antigua fábrica de curtidos","Colecciones de cerámica y objetos etnográficos","Jardín central"],"visita":"horario o cita previa: https://museos.xunta.gal/museos/coleccion-etnografica-e-ceramica-regal-xunqueira","fuentes":["https://www.turismo.gal/recurso/-/detalle/280379512/coleccion-etnografica-e-de-ceramica-regal-xunqueira?langId=es_ES"]},"t:iglesia-de-san-pedro-de-viveiro-vivero":{"municipio":"Vivero","resumen":"Iglesia románica rural declarada Monumento Nacional, ampliada en el siglo XII y reformada en los siglos XVII y XX. Está en la parroquia de San Pedro, a unos kilómetros de la villa. Se la considera de un románico muy puro.","ver_alli":["Canecillos de formas variadas en los aleros","Cordón labrado y roseta sobre el ventanal del ábside","Inscripción epigráfica en el muro izquierdo"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5599/igrexa-parroquial-de-san-pedro-de-viveiro?langId=es_ES"]},"t:monte-san-roque-vivero":{"municipio":"Vivero","resumen":"Monte que se asoma a la ría de Viveiro, con área recreativa, capilla de San Roque, cruceiro y un hórreo. La capilla es un templo sencillo de una nave donde en agosto se celebra romería. Es el mirador clásico sobre la villa y la ría.","ver_alli":["Vistas sobre la ría y el casco urbano","Capilla de San Roque y su cruceiro","Hórreo sobre gran base de piedra"],"visita":"acceso libre","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html","https://query.wikidata.org/ (consulta de elementos con coordenadas, ermida de San Roque de Viveiro)"]},"t:area-etnografica-da-insua-vivero":{"municipio":"Vivero","resumen":"Antiguo cargadero de mineral de hierro del siglo XIX, ligado a las minas de la Silvarosa, que funcionaron hasta 1969. Hoy es un área etnográfica con mirador. Se conservan restos del tranvía aéreo que bajaba el mineral hasta el mar.","ver_alli":["Restos del cargadero y del tranvía aéreo","Mirador sobre la costa de Covas"],"visita":"acceso libre","fuentes":["https://www.paxinasgalegas.es/fiestas/descubre-galicia/descubre-viveiro-159tay.html","https://nominatim.openstreetmap.org/ (Área Etnográfica da Insua)"]},"t:faro-de-roncadoira-xove":{"municipio":"Xove","resumen":"Faro autorizado en 1974 por los numerosos naufragios en la costa de Xove, que no encendió hasta 1986. Su luz está a 94 metros sobre el mar y enlaza los faros de San Cibrao y Estaca de Bares. Es un gran observatorio de aves marinas.","ver_alli":["Panorámica de las islas Coelleira, Sarón y Farallóns","Observación de aves marinas"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/7281/faro-de-roncadoiro?langId=es_ES"]},"t:iglesia-de-san-pedro-de-xuances-xove":{"municipio":"Xove","resumen":"Iglesia de origen románico reconstruida en 1698, con cabecera trazada por Blas de Barros en 1799. Tiene tres naves, crucero con cúpula de media naranja y una elegante torre de dos cuerpos. En el interior hay retablos barroco y renacentista.","ver_alli":["Torre de dos cuerpos con cúpula","Retablo lateral renacentista","Tallas de los siglos XVII-XVIII"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5602/igrexa-parroquial-de-san-pedro-de-xuances?langId=es_ES"]},"t:iglesia-de-san-bartolo-de-xove-xove":{"municipio":"Xove","resumen":"Iglesia de tres naves con primera reforma documentada en 1670 y una inscripción de 1694 en la puerta. Tiene torre con espadaña de dos vanos. Dentro guarda un retablo mayor barroco del siglo XVII y otro renacentista del XVI.","ver_alli":["Inscripción de 1694 en la puerta principal","Retablo renacentista del siglo XVI"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/180409000128/igrexa-de-san-bartolo-de-xove?langId=es_ES"]},"t:iglesia-de-santo-estevo-de-sumoas-xove":{"municipio":"Xove","resumen":"Iglesia del siglo XVII levantada sobre un antiguo castro, con retablo mayor neoclásico.","visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/180405000096/igrexa-parroquial-santo-estevo-de-sumoas?langId=es_ES"]},"t:ponte-do-porto-rio-barba-vicedo":{"municipio":"Vicedo","resumen":"Puente probablemente medieval sobre otro romano, en el camino real entre Viveiro y Ortigueira, que cruza el río Sor. Tiene tres arcos de medio punto de traza románica. En el centro conserva el mojón que marcaba la frontera entre las provincias de Mondoñedo y Betanzos, hoy entre Lugo y A Coruña.","ver_alli":["Mojón de frontera provincial en mitad del puente","Tres arcos de medio punto sobre el Sor"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/19517/ponte-de-o-porto-en-rio-barba?langId=es_ES"],"rp":["r:pr-g-212-ruta-ponte-do-porto-ponte-ullo--a-coruna"]},"t:capilla-de-las-angustias-de-rio-barba-vicedo":{"municipio":"Vicedo","resumen":"Capilla de origen muy antiguo reconstruida en el siglo XVII, junto al Ponte do Porto, a orillas del Sor. Es pequeña y de planta rectangular. Guarda esculturas de los siglos XVI y XVII.","ver_alli":["Esculturas de los siglos XVI y XVII","Entorno del puente y el río Sor"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/22401/capela-das-angustias-de-rio-barba?langId=es_ES"],"rp":["r:pr-g-212-ruta-ponte-do-porto-ponte-ullo--a-coruna"]},"t:iglesia-de-san-paulo-de-rio-barba-vicedo":{"municipio":"Vicedo","resumen":"Iglesia construida a finales del siglo XIV por Fernán Pérez de Andrade. Aún conserva su emblema, el jabalí, en una esquina del tejado. El pórtico es muy posterior.","ver_alli":["Jabalí de los Andrade con cruz en la cubierta","Hornacina con San Paulo en la fachada"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/4998/igrexa-parroquial-de-san-paulo-de-riobarba?langId=es_ES"]},"t:iglesia-de-santa-maria-de-cabanas-vicedo":{"municipio":"Vicedo","resumen":"Iglesia con nave gótica mandada construir por el obispo de Mondoñedo en 1392, y el resto del templo del siglo XVIII. Lleva, como San Paulo de Río Barba, el jabalí de los Andrade. Tiene torre de tres cuerpos con cupulino.","ver_alli":["Nave ojival del siglo XIV","Torre campanario de tres cuerpos","Atrio cubierto para los fieles"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/4996/igrexa-parroquial-de-santa-maria-de-cabanas?langId=es_ES"]},"t:cementerio-indiano-de-xerdiz-orol":{"municipio":"Orol","resumen":"Cementerio construido en 1908 con dinero de 64 vecinos emigrados a Cuba y 110 de la parroquia, considerado el más indiano de A Mariña. Es obra de canteros locales famosos como \"O Pena de Miñotos\". Una placa recuerda a todos los donantes.","ver_alli":["Cruces latinas, penitenciales y de la Trinidad talladas","Piedades en piedra","Placa con los nombres de los donantes"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/240911000153/cemiterio-indiano-de-xerdiz?langId=es_ES"]},"t:iglesia-de-santa-maria-de-xerdiz-orol":{"municipio":"Orol","resumen":"Iglesia de planta de cruz latina y tres naves, junto al cementerio indiano. Guarda una talla protogótica del siglo XIV. Los techos de madera de la capilla mayor tienen pinturas de los cuatro evangelistas.","ver_alli":["Talla del siglo XIV","Pinturas de los evangelistas en el techo"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5591/igrexa-de-santa-maria-de-xerdiz?langId=es_ES"]},"t:casa-do-senoron-casa-de-las-palmeras-orol":{"municipio":"Orol","resumen":"Casa indiana de los años 30 levantada por José García, \"O Señorón\", emigrado a Argentina. Según se cuenta, el constructor la hizo a partir de una foto de la casa del dueño en Argentina. Las palmeras le dan su otro nombre.","ver_alli":["Estilo ecléctico pintoresco","Palmeras del jardín"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/240506000084/casa-do-senoron?langId=es_ES"]},"t:villa-lola-orol":{"municipio":"Orol","resumen":"Casa indiana promovida por la familia Quiza que destaca entre las construcciones de su entorno. Tiene planta en U, a la manera de los palacios barrocos franceses. Mezcla esa idea con la casa tradicional gallega de dos niveles.","ver_alli":["Planta en U de inspiración palaciega","Ornamentación de arquitectura de la emigración"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/240508000168/villa-lola?langId=es_ES"]},"t:antiguas-escuelas-vicente-casavella-orol":{"municipio":"Orol","resumen":"Escuela pagada por Vicente Casavella, vecino de Ourol nacido en 1840 que emigró a Cuba siendo muy pobre. Como no sabía leer ni escribir, quiso que los niños del pueblo tuvieran escuela. Hoy es la sede del ayuntamiento.","ver_alli":["Edificio escolar indiano, hoy casa consistorial"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/240510000261/antiguas-escuelas-vicente-casavella?langId=es_ES"]},"t:iglesia-de-san-pantaleon-de-cabanas-orol":{"municipio":"Orol","resumen":"Iglesia que conserva de su obra gótica de finales del siglo XIV y comienzos del XV la puerta principal. El resto se reformó en el siglo XVIII. La fachada tiene una torre barroca rematada en cúpula.","ver_alli":["Portada gótica con arquillos lobulados y un jabalí","Torre barroca de dos cuerpos"],"visita":"horario de culto","fuentes":["https://www.turismo.gal/recurso/-/detalle/5593/igrexa-de-san-pantaleon-de-cabanas?langId=es_ES"]},"t:ermita-de-nogueira-orol":{"municipio":"Orol","resumen":"Pequeña ermita rústica de principios del siglo XVII, de pizarra encalada. Tiene un pórtico abovedado ante la fachada. Dentro guarda un retablo renacentista con tallas del XVIII.","ver_alli":["Vieira en la clave de la espadaña","Retablo renacentista"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/23923/ermida-de-nogueira?langId=es_ES"]},"t:ermita-de-santa-marina-de-minotos-orol":{"municipio":"Orol","resumen":"Pequeña ermita a orillas del río Besteburíz, cerca de las ruinas del pueblo abandonado de Santa Mariña.","visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/5594/ermida-de-santa-marina-de-minotos?langId=es_ES"]},"t:ferreria-de-bravos-orol":{"municipio":"Orol","resumen":"Antigua ferrería (herrería hidráulica) de la parroquia de Bravos, catalogada por Turismo de Galicia.","visita":"desconocido","fuentes":["https://www.turismo.gal/recurso/-/detalle/21428/ferreria-de-bravos?langId=es_ES"]},"t:torre-de-silan-muras":{"municipio":"Muras","resumen":"Casa-torre medieval que muestra dos épocas en su aparejo. La torre vieja es de finales del siglo XIII o principios del XIV y perdió un piso. En el siglo XV se le añadió el cuerpo de vivienda.","ver_alli":["Puerta de arco de medio punto con anchas dovelas","Diferencia de aparejo entre torre y vivienda"],"visita":"exterior libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/20511/torre-de-silan?langId=es_ES"]},"t:dique-de-bares-dique-fenicio-manon":{"municipio":"Mañón","posicion_nota":"Ubicación sin confirmar: está fuera del pueblo, en el término de Mañón; el punto no marca el sitio.","lat_pueblo":43.7361,"lon_pueblo":-7.7056,"resumen":"Gran espigón de granito del puerto de Bares, el más septentrional de la Península. La tradición y la ficha oficial lo datan en el siglo VII a. C. y lo atribuyen a los fenicios. Mide unos 30 m de largo y 6 de alto y aún protege a las barcas de los vientos del oeste.","ver_alli":["Bloques graníticos del dique"],"visita":"acceso libre","fuentes":["https://www.turismo.gal/recurso/-/detalle/25390/dique-fenicio"]}});